import { useEffect, useRef, useState, useCallback } from 'react';
import { Client } from '@stomp/stompjs';
import type { WebSocketCardData } from '../types/api';

export interface UseCardWebSocketReturn {
  isConnected: boolean;
  isConnecting: boolean;
  cardData: WebSocketCardData | null;
  error: string | null;
  resetCardData: () => void;
  disconnect: () => void;
}

export function useCardWebSocket(isEnabled: boolean = false): UseCardWebSocketReturn {
  const [isConnected, setIsConnected] = useState(false);
  const [isConnecting, setIsConnecting] = useState(false);
  const [cardData, setCardData] = useState<WebSocketCardData | null>(null);
  const [error, setError] = useState<string | null>(null);
  const clientRef = useRef<Client | null>(null);

  const resetCardData = useCallback(() => {
    setCardData(null);
    setError(null);
  }, []);

  const disconnect = useCallback(() => {
    if (clientRef.current) {
      clientRef.current.deactivate();
      clientRef.current = null;
    }
    setIsConnected(false);
    setIsConnecting(false);
    setError(null);
  }, []);

  useEffect(() => {
    if (!isEnabled) {
      disconnect();
      return;
    }

    if (clientRef.current) return;

    setIsConnecting(true);
    setError(null);

    const client = new Client({
      brokerURL: `${import.meta.env.VITE_WEBSOCKET_URL}/web-socket`,
      reconnectDelay: 5000,
      heartbeatIncoming: 4000,
      heartbeatOutgoing: 4000,
      onConnect: (frame) => {
        setIsConnected(true);
        setIsConnecting(false);
        client.subscribe('/queue/access-card', (message) => {
          try {
            const data = JSON.parse(message.body) as WebSocketCardData;
            setCardData(data);
          } catch (parseError) {
            setError('Failed to parse card data');
          }
        });
      },
      onStompError: (frame) => {
        setError(frame.headers['message'] || 'WebSocket connection error');
        setIsConnected(false);
      },
      onWebSocketClose: () => {
        setIsConnected(false);
      }
    });

    client.activate();
    clientRef.current = client;

    return () => {
      disconnect();
    };
  }, [isEnabled, disconnect]);

  return { isConnected, isConnecting, cardData, error, resetCardData, disconnect };
}

function flattenObject(obj: any, prefix: string = ""): any {
  let flattened: any = {};
  for (const key in obj) {
    if (Object.prototype.hasOwnProperty.call(obj, key)) {
      const value = obj[key];
      const prefixedKey = prefix === "" ? key : `${prefix}.${key}`;
      if (
        typeof value === "object" &&
        value !== null &&
        !Array.isArray(value)
      ) {
        const nested = flattenObject(value, prefixedKey);
        flattened = { ...flattened, ...nested };
      } else if (Array.isArray(value)) {
        flattened[prefixedKey] = "";
      } else {
        flattened[prefixedKey] = value;
      }
    }
  }
  return flattened;
}

function formatObject(obj: any): string {
  const flattened = flattenObject(obj);
  let result = "";
  Object.keys(flattened)
    .sort()
    .forEach((key) => {
      const value = flattened[key];
      result += `${key}${value}`;
    });
  return result;
}

export const makeSignature = (
  email: number,
  timestamp: number,
  data: any,
  isFormData?: boolean
) => {
  const formDataObject: any = {
    email,
    timestamp,
  };
  if (isFormData) {
    for (const pair of data.entries()) {
      formDataObject[pair[0]] = pair[1];
    }
  }
  const newPayload = {
    email,
    ...data,
    timestamp,
  };
  const newData = isFormData ? formDataObject : newPayload;
  const finalPayload = formatObject(newData);
  return CryptoJS.SHA1(finalPayload);
};

