import React, { useEffect, useRef, useState } from "react";

interface IPropsVideoMSE {
  localCamera?: { ws?: string; cctvName?: string };
}

export const VideoMSE: React.FC<IPropsVideoMSE> = ({ localCamera }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const [loading, setLoading] = useState<boolean>(true);

  useEffect(() => {
    if (!localCamera?.ws) return;

    let mseQueue: Uint8Array[] = [];
    let mseSourceBuffer: SourceBuffer | null = null;
    let mseStreamingStarted = false;
    let ws: WebSocket | null = null;

    const pushPacket = () => {
      const videoEl = videoRef.current;
      if (!videoEl || !mseSourceBuffer) return;

      if (!mseSourceBuffer.updating) {
        if (mseQueue.length > 0) {
          const packet = mseQueue.shift();
          if (packet) mseSourceBuffer.appendBuffer(packet);
        } else {
          mseStreamingStarted = false;
        }
      }

      if (videoEl.buffered.length > 0 && typeof document.hidden !== "undefined" && document.hidden) {
        videoEl.currentTime = videoEl.buffered.end(videoEl.buffered.length - 1) - 0.5;
      }
    };

    const readPacket = (packet: Uint8Array) => {
      if (!mseStreamingStarted && mseSourceBuffer) {
        mseSourceBuffer.appendBuffer(packet);
        mseStreamingStarted = true;
        return;
      }
      mseQueue.push(packet);
      if (mseSourceBuffer && !mseSourceBuffer.updating) {
        pushPacket();
      }
    };

    const startPlay = (videoEl: HTMLVideoElement, url: string) => {
      const mse = new MediaSource();
      videoEl.src = window.URL.createObjectURL(mse);

      mse.addEventListener("sourceopen", () => {
        ws = new WebSocket(url);
        ws.binaryType = "arraybuffer";
        ws.onopen = () => setLoading(true);

        ws.onmessage = (event) => {
          setLoading(false);
          const data = new Uint8Array(event.data);

          if (data[0] === 9) {
            const decodedArr = data.slice(1);
            const mimeCodec = window.TextDecoder ? new TextDecoder("utf-8").decode(decodedArr) : "avc1.640029";
            mseSourceBuffer = mse.addSourceBuffer(`video/mp4; codecs="${mimeCodec}"`);
            mseSourceBuffer.mode = "segments";
            mseSourceBuffer.addEventListener("updateend", pushPacket);
          } else {
            readPacket(data);
          }
        };
      }, false);
    };

    const videoEl = videoRef.current;
    if (videoEl) startPlay(videoEl, localCamera.ws);

    return () => {
      if (ws) ws.close();
    };
  }, [localCamera?.ws]);

  return (
    <div className="relative w-full h-full bg-black rounded-lg" style={{ aspectRatio: "16/9" }}>
      <video ref={videoRef} autoPlay muted playsInline className="w-full h-full object-contain" />
    </div>
  );
};

import React, { useEffect, useRef, useState } from "react";
import JSMpeg from "@cycjimmy/jsmpeg-player";
import { Loader2, Video, Expand } from "lucide-react";

export interface JsmpegPlayerRef {
  play: () => void;
  pause: () => void;
  stop: () => void;
  destroy: () => void;
}

interface JsmpegPlayerProps {
  videoUrl: string;
  options?: object;
  overlayOptions?: object;
  onRef?: (ref: JsmpegPlayerRef) => void;
  cameraName?: string;
  onExpand?: () => void;
}

export const JsmpegPlayer: React.FC<JsmpegPlayerProps> = ({ videoUrl, options, overlayOptions, onRef, cameraName, onExpand }) => {
  const videoWrapperRef = useRef<HTMLDivElement | null>(null);
  const [playing, setPlaying] = useState<boolean>(false);

  useEffect(() => {
    const wrapper = videoWrapperRef.current;
    if (!wrapper) return;

    wrapper.innerHTML = "";
    const newVideo = new JSMpeg.VideoElement(
      wrapper,
      videoUrl,
      { ...options, control: false },
      {
        ...overlayOptions,
        onVideoDecode: (decoded: boolean) => setPlaying(Boolean(decoded)),
      }
    );

    if (onRef) {
      onRef({
        play: () => newVideo.play(),
        pause: () => newVideo.pause(),
        stop: () => newVideo.stop(),
        destroy: () => newVideo.destroy(),
      });
    }

    const canvas = wrapper.querySelector("canvas");
    if (canvas) {
      canvas.style.width = "100%";
      canvas.style.height = "100%";
      canvas.style.display = "block";
      canvas.style.objectFit = "contain";
    }

    return () => {
      try {
        setPlaying(false);
        newVideo.destroy();
      } catch (error) {
        console.error("Error destroying JSMpeg video:", error);
      }
    };
  }, [videoUrl, options, overlayOptions, onRef]);

  return (
    <div className="relative w-full">
      <div ref={videoWrapperRef} className="w-full h-full" />
      {!playing && (
        <div className="absolute inset-0 flex justify-center items-center bg-black/20">
          <Loader2 className="animate-spin text-white" />
        </div>
      )}
      {cameraName && (
        <div className="absolute bottom-1 left-1 flex items-center gap-1 text-white ml-3">
          <Video size={16} />
          <p className="text-sm">{cameraName}</p>
        </div>
      )}
      {playing && onExpand && (
        <button className="cursor-pointer absolute bottom-1 right-1 bg-white/90 rounded p-1 mr-3" onClick={onExpand}>
          <Expand size={16} />
        </button>
      )}
    </div>
  );
};

import React, { useEffect, useState, useRef } from "react";
